import six
import subprocess
from threading import Timer


class LogLevel(object):
    Trace = 'TRACE'
    Info = 'INFO'
    Debug = 'DEBUG'
    Warn = 'WARN'


class RobotCommand(object):
    DEFAULT_PATH = ''

    def __init__(self):
        if six.PY2:
            self._command = ['python2.7', '-m', 'robot']
        else:
            self._command = ['python3', '-m', 'robot']

        self._process = None
        self._data_sources_path = []

    def set_tests(self, data_sources_path):
        self._data_sources_path = [data_sources_path]
        return self

    def set_output_dir(self, output_dir):
        if self._exists_in_command('-d'):
            self._replace('-d', output_dir)
        else:
            self._command += ['-d', output_dir]
        return self

    def set_configuration(self, config):
        if self._exists_in_command('-v'):
            self._replace('-v', config)
        else:
            self._command += ['-v', config]
        return self

    def set_custom_args(self, args):
        self._command += args
        return self

    def set_loglevel(self, level):
        self._command += ['-L', level]
        return self

    def set_testcase(self, testcase_name):
        if self._exists_in_command('-t'):
            self._replace('-t', testcase_name)
        else:
            self._command += ['-t', testcase_name]
        return self

    def set_listener(self, listener_path):
        self._command += ['--listener', listener_path]
        return self

    def _exists_in_command(self, param_name):
        return param_name in self._command

    def _replace(self, param_name, value):
        self._command[self._command.index(param_name) + 1] = value

    def command(self):
        return self._command + self._data_sources_path

    def command_name(self):
        return self._command[0]

    def args(self):
        return self.command()[1:]

    def execute(self):
        if not self._data_sources_path:
            raise Exception('Robot command should contain path to data sources')

        self._process = subprocess.Popen(self.command())
        self._process.wait()

    def stop(self, timeout=10.0):
        if self._process is None or self._process.poll() is not None:
            return

        try:
            timer = Timer(timeout, self.kill_process)
            timer.start()
            self._process.terminate()
            self._process.wait()
            timer.cancel()
        except Exception as e:
            raise Exception('Stopping robot command process failed. ERROR: {}'.format(str(e)))

    def kill_process(self):
        self._process.kill()
        self._process.wait()


class Robot3Command(RobotCommand):
    DEFAULT_PATH = ''

    def __init__(self):
        super(Robot3Command, self).__init__()
        self._command = ['python3', '-m', 'robot']
